#!/bin/sh
# scripts/bump-version.sh — move every version site to the new literal, in one commit.
#
# usage: scripts/bump-version.sh OLD NEW      e.g. bump-version.sh 0.3.0-beta 0.4.0-beta.1
#
# Edits: Cargo.toml, src-tauri/Cargo.toml, src-tauri/tauri.conf.json,
# Cargo.lock (regenerated by cargo, see below). Then greps the tree for the
# old literal and lists every remaining site for the eye to judge.
set -eu

OLD="${1:?usage: bump-version.sh OLD NEW}"
NEW="${2:?usage: bump-version.sh OLD NEW}"
[ "$OLD" != "$NEW" ] || { echo "OLD and NEW are the same — nothing to do"; exit 1; }

echo "== version sites edited =="
for f in Cargo.toml src-tauri/Cargo.toml src-tauri/tauri.conf.json; do
  n=$(grep -c "$OLD" "$f" || true)
  if [ "$n" -gt 0 ]; then
    sed -i '' "s/$OLD/$NEW/g" "$f"
    echo "  $f ($n site(s))"
  else
    echo "  $f — the old literal is not there (already bumped?), left alone"
  fi
done

# The Cargo.lock's own `name = "fleet"` / `name = "fleet-desktop"` entries
# carry the version — and ONLY those. A blind sed moves every other crate
# carrying the same literal (approx 0.5.1, ghash 0.5.1) and mangles crates
# one digit apart (crossbeam-channel 0.5.17 turned into 0.6.07 — an
# unparseable lock, caught by the next cargo invocation).
python3 - "$OLD" "$NEW" <<'PYEOF'
import sys
old, new = sys.argv[1], sys.argv[2]
lines = open("Cargo.lock").read().split("\n")
moved = 0
for i in range(len(lines) - 1):
    if lines[i] in ('name = "fleet"', 'name = "fleet-desktop"'):
        assert lines[i + 1].startswith("version = "), lines[i + 1]
        if old in lines[i + 1]:
            lines[i + 1] = lines[i + 1].replace(old, new)
            moved += 1
print(f"  Cargo.lock (fleet/fleet-desktop entries moved: {moved})")
PYEOF

echo "== remaining sites carrying $OLD (judge each) =="
grep -rn --exclude-dir=.git --exclude-dir=target --exclude-dir=node_modules \
  --exclude-dir=services --exclude-dir=docs -e "$OLD" \
  Cargo.toml Cargo.lock src src-tauri scripts README.md CHANGELOG.md 2>/dev/null || echo "  none"
